-- fdh-c-check: op row count of INS
-- GENERATED by scripts/export_rules.mjs from BKH Insight src/app/api/fdh/c-check/checks.ts - do not edit by hand
-- params (2, in order of the placeholders): start, end
-- returns n
WITH p AS (SELECT CAST(? AS DATE) AS s, CAST(? AS DATE) AS e) SELECT COUNT(*) AS n FROM p JOIN ovst v ON v.vstdate BETWEEN p.s AND p.e INNER JOIN patient pt ON pt.hn = v.hn LEFT JOIN patient_pttype pp ON pp.hn = v.hn AND pp.pttype = v.pttype WHERE v.an IS NULL OR v.an = '';
